INSERT INTO `ai_ideas` (`id`, `company_id`, `user_input_topic`, `platform`, `campaign_type`, `generated_title`, `generated_description`, `generated_hashtags`, `image_suggestion_prompt`, `is_selected`, `created_at`, `updated_at`, `suggested_layout`, `content_items`, `suggested_font`, `design_layers`, `topic_id`, `marketing_angle`, `post_format`, `ai_score`, `performance_metrics`, `image_url`) VALUES
(1, 11, '8 mart', 'Instagram', 'product_launch', '8 Mart Moda Lansmanı', 'fsdfa\'nın yeni moda koleksiyonuyla 8 Mart\'ta tarzınızı konuşturun! 💃 Yeni tasarımlarımızı keşfedin ve stilinize renk katın. #YeniSezon #Moda', '#8Mart #ModaLansmanı #YeniKoleksiyon #StilSahibi', 'A vibrant and modern fashion scene with a variety of stylish dresses and accessories displayed in a sunlit boutique window. The mood is fresh and trendy, with colors like coral, teal, and soft gold dominating the palette. The composition includes mannequins dressed in chic outfits and reflections of the city street outside.', 1, '2026-04-02 21:28:30.870', '2026-04-02 21:28:48.502', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(2, 11, '8 mart', 'Instagram', 'product_launch', 'Kadınlar Günü Özel Koleksiyonu', 'Kadınlar Günü\'nde fsdfa\'nın özel koleksiyonuyla kendinizi ödüllendirin. Yeni moda trendleri ve benzersiz tasarımlar sizi bekliyor! 👗✨', '#KadınlarGünü #ÖzelKoleksiyon #fsdfaModa #Stil', 'An elegant fashion display showcasing an exclusive collection for Women\'s Day. The scene is set in a luxurious boutique with rich fabrics and delicate details. Warm lighting highlights the garments, and the color scheme features deep purples and emerald greens for a sophisticated and luxurious feel.', 0, '2026-04-02 21:28:30.872', '2026-04-02 21:28:30.872', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(3, 11, '8 mart', 'Instagram', 'product_launch', 'Tarzınızı Yenileyin: fsdfa', 'fsdfa\'nın yeni koleksiyonuyla tarzınızı baştan yaratın! 🔥 Eğlenceli ve yaratıcı tasarımlarımızla 8 Mart\'ta göz kamaştıracaksınız. Hemen keşfedin!', '#TarzYenileme #ModaTrendleri #fsdfaKoleksiyon #8Mart', 'A creative and energetic fashion scene highlighting bold and innovative designs. The setting is a vibrant studio with playful patterns and dynamic shapes. Bright and contrasting colors such as electric blue, fiery red, and neon yellow are used to convey a sense of excitement and creativity.', 0, '2026-04-02 21:28:30.874', '2026-04-02 21:28:30.874', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(4, 11, 'sevgililer günü', 'Instagram', 'product_launch', 'Sevgililer Günü Işıltısını Keşfet', 'Bu Sevgililer Günü\'nde fsdfa\'nın en yeni moda koleksiyonuyla aşkınızı ifade edin. Sadece sevdiğiniz için değil, kendiniz için de parlayın. 🥰✨', '#SevgililerGünü #fsdfamoda #Aşk #ModaTrendleri #ValentinesDay', 'A romantic scene at dusk featuring a couple holding hands while walking through a stylish, fashionable street lined with twinkling fairy lights. The colors are soft pastels, creating a warm, inviting mood. The focus is on the couple\'s matching stylish outfits, with a gentle bokeh effect from the lights in the background, emphasizing a sense of romance and style.', 1, '2026-04-02 21:44:04.872', '2026-04-02 21:44:16.634', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(5, 11, 'sevgililer günü', 'Instagram', 'product_launch', 'Aşkın En Güzel Hali', 'fsdfa ile Sevgililer Günü\'nde kendinizi şımartın. Yeni koleksiyonumuzla kendinize ve sevdiğinize unutulmaz bir hediye verin. 💝💃', '#Moda #SevgililerGünüHediyesi #fsdfa #Fashion #Love', 'A close-up of elegant, fashionable clothing items neatly arranged on a soft velvet surface. The colors are deep reds and golds, with a touch of sparkle to evoke a luxurious feel. A subtle heart-shaped shadow is cast by soft light, adding a romantic atmosphere without using any text or words.', 0, '2026-04-02 21:44:04.883', '2026-04-02 21:44:04.883', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(6, 11, '23 nisan', 'Instagram', 'event', '23 Nisan Coşkusu: Moda İle Kutla!', '23 Nisan\'ın çocuk ruhunu modayla yaşa! En güzel kombinlerle bayrama hazır olun. 🎉 #fsdfa #ModaEtkinlikleri #23NisanModası', '#fsdfa #ModaEtkinlikleri #23NisanModası', 'A vibrant and colorful image capturing the essence of a joyful spring celebration. Display a lively outdoor scene with children playing happily in fashionable, colorful clothing. Include bright flowers and balloons to evoke a festive atmosphere. The mood is cheerful and celebratory with warm sunlight casting soft shadows.', 0, '2026-04-02 23:37:33.519', '2026-04-02 23:37:33.519', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(7, 11, '23 nisan', 'Instagram', 'event', '23 Nisan Şıklığı', '23 Nisan\'da stilinizle fark yaratın! Özel gün için tasarladığımız koleksiyonla şıklığınızı gösterin. 🌟 #fsdfa #Stil #BaharModası', '#fsdfa #Stil #BaharModası', 'An elegant and fashion-forward scene showcasing stylish spring apparel. Picture a young adult dressed in a chic and modern outfit, standing confidently in a sunlit park. Surround them with blooming trees and vibrant flowers. The colors are soft pastels and earth tones, creating a sophisticated yet approachable vibe.', 1, '2026-04-02 23:37:33.536', '2026-04-02 23:37:46.835', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(8, 11, '23 nisan', 'Instagram', 'event', 'Rengarenk 23 Nisan', 'Bu 23 Nisan, renklerin gücüyle dolu bir kutlama yapalım! Giydiklerinizle çevrenizi aydınlatın. 💐 #fsdfa #RenkliTarz #23Nisan', '#fsdfa #RenkliTarz #23Nisan', 'A bright and colorful celebration scene with diverse people wearing colorful clothes, embodying the spirit of unity and joy. Include a backdrop of urban landscapes with spontaneous street performances and vibrant cultural elements. The colors are bold and varied, creating a dynamic and inclusive atmosphere.', 0, '2026-04-02 23:37:33.544', '2026-04-02 23:37:33.544', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(9, 11, '23 nisan', 'Instagram', 'event', '23 Nisan Coşkusu', 'fsdfa moda ile 23 Nisan coşkusunu kutluyor! Renkli kombinlerle çocukların bayramını daha da özel yapalım. 🎈👗', '#23Nisan #Moda #ÇocukBayramı #fsdfaStyle', 'A vibrant outdoor scene of a children\'s festival with colorful balloons and playful decorations. Children wearing stylish, modern outfits are joyfully playing in a park. Bright spring colors dominate the scene, creating a festive and happy atmosphere.', 1, '2026-04-02 23:45:37.721', '2026-04-02 23:45:41.118', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(10, 11, '23 nisan', 'Instagram', 'event', '23 Nisan Tasarım Yarışması', 'fsdfa moda ile 23 Nisan\'a özel tasarım yarışmamıza katıl! En yaratıcı kombinini bizimle paylaş ve sürpriz hediyeler kazanma şansı yakala. 🎉', '#TasarımYarışması #Moda #fsdfaStyle #23Nisan', 'A creative, artistic mood board filled with sketches of children\'s fashion designs. The board is colorful, showcasing various textures and fabric swatches. The background is a light pastel color, giving a fresh and innovative feel to the image.', 0, '2026-04-02 23:45:37.732', '2026-04-02 23:45:37.732', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(11, 11, '23 nisan', 'Instagram', 'event', '23 Nisan Moda Tüyoları', 'fsdfa moda\'dan 23 Nisan\'a özel stil tüyolarıyla çocuğunuzun stilini renklendirin! Renk uyumları ve rahat kombinler için takipte kalın! 🌟', '#StilTüyoları #fsdfaModa #ÇocukStili #23Nisan', 'A close-up flat lay of colorful children\'s fashion items neatly arranged on a white surface. Include vibrant shirts, cute hats, and fun accessories. The composition is bright and cheerful, evoking a sense of style and playfulness.', 0, '2026-04-02 23:45:37.737', '2026-04-02 23:45:37.737', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(12, 11, '19 mayıs', 'Instagram', 'event', 'Stilini Yansıtan Enerji', '19 Mayıs coşkusunu modayla birleştir! fsdfa\'nın özel koleksiyonuyla bu anlamlı günü kutla. Giydiklerinle geçmişe saygı, geleceğe umut taşı.', '#19Mayıs #fsdfaModa #StiliniYansıt #TurkishYouthDay', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A dynamic and vibrant scene showcasing a young adult in a stylish outfit from the fsdfa collection, standing confidently in a sunlit urban park. The colors are lively with red and white accents, symbolizing the Turkish flag. The mood is energetic and inspiring, reflecting youthful spirit and pride.', 0, '2026-04-03 00:11:29.327', '2026-04-03 00:11:29.327', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(13, 11, '19 mayıs', 'Instagram', 'event', 'Gençliğin Modası: fsdfa ile 19 Mayıs', '19 Mayıs\'a özel fsdfa moda koleksiyonu seni bekliyor! Gençliğin enerjisini ve tarzını yansıtan parçalarla bu günü kutla ve fark yarat.', '#GençlikVeSporBayramı #fsdfa #ModaTutkusu #YouthFashion', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A lively group of young people dressed in vibrant fsdfa outfits, laughing and enjoying a sunny day at a cultural festival. The scene captures diversity and unity, with a backdrop of colorful flags and festive decorations. The mood is joyful and free-spirited, with bright colors highlighting the spirit of celebration.', 1, '2026-04-03 00:11:29.340', '2026-04-03 00:11:57.316', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(14, 12, 'Summer collection promotion for a fashion brand. Beach dress photo.', 'Instagram', 'brand_awareness', 'Sahil Modası: Test Brand ile Buluşun', 'Yazın sıcak esintisiyle sahil modası Test Brand ile canlanıyor. Bu eşsiz koleksiyonla her anı stil dolu yaşayın! 🏖️🌞 #TestBrandModa #YazStili', '#TestBrandModa #YazStili #BeachDress #SummerCollection #Moda2023', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A stunning beach scene featuring a stylish beach dress from Test Brand\'s summer collection. The dress is flowing in the gentle sea breeze, with its vibrant colors standing out against the clear blue sky and golden sandy beach. The mood is carefree and joyful, capturing the essence of a perfect summer day.', 1, '2026-04-03 14:51:05.428', '2026-04-03 14:53:00.330', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(15, 12, 'Summer collection promotion for a fashion brand. Beach dress photo.', 'Instagram', 'brand_awareness', 'Yazın Renkleri Test Brand İle Canlanıyor', 'Plaj görünümlerinde farklılaşmanın tam zamanı! Test Brand yaz koleksiyonundaki plaj elbiseleri ile yazın renklerini üzerinizde taşıyın. 🌊👗 #TestBrandYaz #ModaTutkusu', '#TestBrandYaz #ModaTutkusu #SummerFashion #BeachWear #FashionLovers', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A vibrant and colorful beach setting showcasing a woman wearing a beach dress from Test Brand\'s summer collection. The dress features bright, bold patterns that pop against the serene backdrop of the ocean and sky. The mood is vibrant and lively, embodying the joyful spirit of summer fashion.', 0, '2026-04-03 14:51:05.439', '2026-04-03 14:51:05.439', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(16, 12, 'Summer collection promotion for a fashion brand. Beach dress photo.', 'Instagram', 'brand_awareness', 'Test Brand Yaz Koleksiyonuyla Plajlarda Fark Yaratın', 'Test Brand’in yaz koleksiyonu ile plajların yıldızı olun. Şıklığın ve rahatlığın buluştuğu bu elbiselerle kendinizi özel hissedin! ☀️👗 #PlajModa #TestBrandFarkı', '#PlajModa #TestBrandFarkı #SummerVibes #BeachFashion #Fashionista', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. An elegant beach setting with a stunning beach dress from Test Brand\'s summer collection displayed prominently. The dress is elegant and chic, with soft pastel colors that blend perfectly with the gentle waves and the soft, sandy beach. The mood is classy and serene, capturing the relaxed yet sophisticated ambiance of a summer day at the beach.', 0, '2026-04-03 14:51:05.444', '2026-04-03 14:51:05.444', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(17, 16, '19 mayıs', 'Instagram', 'event', '19 Mayıs Enerjisi Modayla Buluşuyor!', '19 Mayıs\'ta gençlik enerjisini stilinize yansıtın! Dio şirketi olarak, sizlere özel koleksiyonumuzla farklı bir moda deneyimi sunuyoruz. Dijitalde fark yaratmanın tam zamanı!', '#19Mayıs #DioŞirketi #Moda #DigitaldeFarkYarat #Fashion #Style', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A vibrant and dynamic scene of a young adult wearing a stylish, modern outfit from Dio şirketi\'s collection, standing in a sunlit urban setting. The colors are bold and youthful, capturing the energy of 19 Mayıs, with an emphasis on the smooth texture of the fabric and the natural flow of the outfit, creating a lively and engaging mood.', 1, '2026-04-03 15:03:50.408', '2026-04-03 15:03:54.644', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(18, 16, '19 mayıs', 'Instagram', 'event', 'Dijitalde Gençlik İkonları: Dio ile 19 Mayıs', '19 Mayıs, genç ruhları modanın gücüyle bir araya getiriyor! Dio\'nun şık tasarımlarıyla dijital dünyada fark yaratın. Gençlik ve stil bir arada!', '#Gençlik #DioModa #19Mayıs #FashionIcons #DigitalFashion', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A scene depicting a group of young adults showcasing Dio şirketi\'s latest fashion collection, standing together in a beautifully lit, contemporary urban environment. The clothing is sleek and modern, with vibrant colors and intricate details, conveying a sense of unity and youthful energy, perfectly aligned with the theme of 19 Mayıs.', 0, '2026-04-03 15:03:50.421', '2026-04-03 15:03:50.421', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(19, 17, 'Summer beach fashion', 'Instagram', 'brand_awareness', 'Yazın Parlayan Stili: Dio', 'Sahil şıklığınızı tamamlayacak Dio koleksiyonuyla tanışın. Renklerin ve desenlerin mükemmel uyumuyla plaj modasını yeniden tanımlayın. 🌊☀️', '#DioModa #YazStili #BeachFashion #SummerVibes', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A vibrant beach scene featuring an array of colorful and stylish Dio beachwear laid out on pristine white sand, with turquoise ocean waves gently lapping at the shore. Bright, lively colors like coral, turquoise, and sunny yellow dominate, evoking a cheerful and inviting summer mood.', 1, '2026-04-03 15:56:45.189', '2026-04-03 15:56:58.681', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(20, 17, 'Summer beach fashion', 'Instagram', 'brand_awareness', 'Dio ile Plajda Zarafet', 'Plajda göz alıcı olmanın sırrı Dio’nun zarif tasarımlarında saklı. İkonik parçalarla sahilde her daim dikkatleri üzerinize çekin. 🏖️✨', '#DioEtkisi #PlajModası #BeachElegance #ModaTutkusu', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. An elegantly styled beach scene showcasing Dio\'s sophisticated beachwear hanging from a wooden cabana against a backdrop of a serene ocean under a clear blue sky. Neutral tones like beige, white, and soft pinks highlight the chic and graceful fashion pieces, creating a sense of luxury and refinement.', 0, '2026-04-03 15:56:45.205', '2026-04-03 15:56:45.205', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(21, 17, 'Summer beach fashion', 'Instagram', 'brand_awareness', 'Dio’nun Enerjisiyle Plajda Parla', 'Yazın enerjisini yansıtan Dio parçalarıyla plajda fark yaratın. Canlı renklerle dolup taşan sahiller sizi bekliyor! 🌈🌴', '#DioYaz #RenkliPlaj #VibrantStyle #SummerReady', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A lively, colorful display of Dio beach fashion, including vibrant swimwear and accessories, arranged artfully on a bright sunlit beach towel. Bold colors such as fuchsia, lime green, and electric blue pop against the golden sand, conveying a playful and energetic summer vibe.', 0, '2026-04-03 15:56:45.210', '2026-04-03 15:56:45.210', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(22, 18, '19 mayıs', 'Instagram', 'product_launch', '19 Mayıs\'a Özel Lezzetler Dio LTF\'de!', '19 Mayıs coşkusunu Dio LTF\'nin özel lezzetleriyle kutlayın! Yeni ürün serimizle lezzet yolculuğuna çıkın. Siz de keşfedin, tatilin tadını çıkarın! 🥳🎉', '#19Mayıs #YeniLezzetler #DioLTF #Yiyecek #GençlikBayramı', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A vibrant scene showcasing a variety of fresh, colorful food products beautifully arranged on a wooden table. The setting is outdoors, capturing the festive mood of a national holiday, with sunlight streaming through nearby trees. Rich tones of red, green, and yellow dominate, creating an appetizing and inviting atmosphere.', 1, '2026-04-03 19:54:45.724', '2026-04-03 19:54:57.470', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(23, 18, '19 mayıs', 'Instagram', 'product_launch', 'Dio LTF\'den 19 Mayıs\'a Özel Lezzet Keşfi!', '19 Mayıs\'ta yenilikleri keşfedin! Dio LTF\'nin yeni tatlarıyla Gençlik ve Spor Bayramı\'nı lezzetle kutlayın. Yeni ürünlerimizi mutlaka deneyin! 🎈🥗', '#DioLTF #19Mayıs #LezzetKeşfi #Yiyecek #GençlikBayramı', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. An elegant flat-lay image of a variety of gourmet dishes on a rustic wooden table. The dishes are meticulously arranged to highlight vibrant ingredients, creating a sense of abundance and celebration. The lighting is warm, casting gentle shadows that enhance the textures and colors of the food, suggesting a festive and joyful occasion.', 0, '2026-04-03 19:54:45.737', '2026-04-03 19:54:45.737', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(24, 19, '21 mart kadınlar günü ile ilgili üstünde firma adının bulunduğu ve her ırktan kadının bulunduğu bir görsel', 'Instagram', 'brand_awareness', 'Kadınlar Günü\'nde Her Şeye Değer!', 'Assas ile her ırktan kadının güzelliğini ve gücünü kutluyoruz! 💪👗 21 Mart\'ta kadınlara özel sürprizlerimiz var, göz atmayı unutma! #KadınlarGünü #AssasModa', '#KadınlarGünü #AssasModa #GüçlüKadınlar #Moda #Fashion', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A diverse group of women from different ethnic backgrounds standing together, smiling, and wearing fashionable outfits representative of the brand\'s style. The scene is vibrant with warm tones, portraying unity and empowerment. No text, letters, or numbers in the image.', 1, '2026-04-04 11:16:21.936', '2026-04-04 11:16:35.596', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(25, 19, '21 mart kadınlar günü ile ilgili üstünde firma adının bulunduğu ve her ırktan kadının bulunduğu bir görsel', 'Instagram', 'brand_awareness', 'Moda İle Fark Yarat!', 'Assas olarak her yaştan ve her ırktan kadının yanında olmanın gururunu yaşıyoruz. Sen de bu özel günün tadını çıkart! 💖👠 #FarkYaratanKadınlar', '#FarkYaratanKadınlar #AssasModa #KadınlarGünü #Diversity #Empowerment', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. Women of various ethnicities joyfully interacting, showcasing unique clothing pieces. The background is a chic urban setting, with soft, natural lighting that highlights the diversity and harmony among them. No text, letters, or numbers in the image.', 0, '2026-04-04 11:16:21.952', '2026-04-04 11:16:21.952', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(26, 19, '21 mart kadınlar günü ile ilgili üstünde firma adının bulunduğu ve her ırktan kadının bulunduğu bir görsel', 'Instagram', 'brand_awareness', 'Kadınlar Günü\'ne Özel Işılda!', 'Her ırktan kadınların zarafetini ve stilini kutluyoruz. Assas ile kendi yolunu çiz ve ışığını yay! ✨👗 #KadınGibiGüzel', '#KadınGibiGüzel #AssasModa #WomenEmpowerment #21Mart', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A group of women, each from a different ethnic background, elegantly posing in stylish outfits. The setting is an open field with natural sunlight, creating a serene and uplifting atmosphere. The diversity in fashion and facial expressions captures their unique beauty. No text, letters, or numbers in the image.', 0, '2026-04-04 11:16:21.954', '2026-04-04 11:16:21.954', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(27, 19, 'kuruluş yılı', 'Instagram', 'product_launch', 'Yeni Başlangıçlar Zamanı!', 'Merhaba sevgili moda tutkunları! assas ailesi olarak kuruluş yılımızda sizlere yepyeni bir koleksiyon sunuyoruz. Her parçada kendinizi bulacağınız bu koleksiyonu kaçırmayın! 🤩 #assasModası', '#kuruluşyılı #modaseverler #assas #yenikoleksiyon #fashionlaunch', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A group of young people, aged 18-35, happily interacting and trying on stylish, modern fashion pieces from the new collection in a chic, trendy boutique setting. The clothing should feature vibrant colors and patterns, with a focus on joy and excitement.', 0, '2026-04-04 11:25:19.320', '2026-04-04 11:25:19.320', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(28, 19, 'kuruluş yılı', 'Instagram', 'product_launch', 'Koleksiyon Tanışma Partisi!', 'assas\'tan yepyeni bir koleksiyon geliyor ve biz bunu sizlerle kutluyoruz! Bu özel günümüzde bize katılın, modanın keyfini çıkarın. ❤️🎉 #assasAilesi', '#kuruluşyılı #moda #assas #parti #newcollection', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A festive, celebratory atmosphere featuring a beautifully styled table with the latest fashion pieces elegantly displayed. Young, stylish individuals are mingling and admiring the collection, surrounded by festive decorations and soft, warm lighting.', 0, '2026-04-04 11:25:19.328', '2026-04-04 11:25:19.328', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(29, 19, 'kuruluş yılı', 'Instagram', 'product_launch', 'Moda Hikayemiz Başlıyor!', 'assas moda dünyasına adım attı! Yeni koleksiyonumuzla tanışın ve kendi tarzınızı yaratın. 👗✨ Her şey sizin için, samimiyetle tasarlandı. #assasTarzı', '#kuruluşyılı #tarzınayansıt #assas #fashionjourney #style', 'Photorealistic, 8k, ultra-realistic, highly detailed photography, natural lighting, smooth texture, professional product photography. A close-up of an intricately designed, fashionable outfit from the new collection, with vibrant textures and patterns. The setting is a minimalist, stylish background, emphasizing the craftsmanship and modern design elements.', 0, '2026-04-04 11:25:19.332', '2026-04-04 11:25:19.332', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(30, 19, 'markanın logosunu kullanarak çanakkale şehitleri ile ilgili görsel üret üzerinde açıklama olsun', 'Instagram', 'sales', 'Kahramanlarımızı Unutmayalım', 'Çanakkale’de kahramanlık destanı yazanları saygıyla anıyoruz. assas olarak, onların cesaretinden ilham alarak moda dünyasında yenilikler yaratıyoruz. Gelin, birlikte tarihe tanıklık edelim!', '#Çanakkale #Kahramanlar #Moda #assas #BirlikteGüçlüyüz', 'A visually captivating scene of serene fields under a clear sky, with golden sunlight casting a warm glow. In the background, faint silhouettes of historical monuments to evoke a sense of pride and remembrance. The mood is respectful and uplifting, with earthy tones creating a harmonious and heartfelt atmosphere.', 1, '2026-04-04 12:07:36.338', '2026-04-04 12:07:42.419', 'right_bottom', '[{\"icon\":\"🌟\",\"title\":\"Kahramanlık\"},{\"icon\":\"❤️\",\"title\":\"Saygı ve Anma\"},{\"icon\":\"👗\",\"title\":\"Moda İlhamı\"}]', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(31, 19, 'markanın logosunu kullanarak çanakkale şehitleri ile ilgili görsel üret üzerinde açıklama olsun', 'Instagram', 'sales', 'Çanakkale’nin İzinde', 'Tarihimizde iz bırakan Çanakkale ruhunu, assas modasıyla birleştiriyoruz. Cesaret ve şıklığın buluştuğu bu özel kampanyaya sen de katıl!', '#ÇanakkaleRuhu #assasModa #CesaretVeŞıklık', 'A creatively designed image showing a sunset over calm waters, with a blend of fiery oranges and cool blues. In the foreground, abstract representations of fashion elements subtly integrated into the landscape. The mood is tranquil and inspiring, using soft gradients to highlight the peaceful yet powerful theme.', 0, '2026-04-04 12:07:36.346', '2026-04-04 12:07:36.346', 'left_top', '[{\"icon\":\"🔥\",\"title\":\"Cesaret\"},{\"icon\":\"💃\",\"title\":\"Şıklık\"},{\"icon\":\"🌅\",\"title\":\"İlham Verici\"}]', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
