INSERT INTO `product_image_variants` (`id`, `studio_id`, `variant_key`, `name`, `platform`, `format_label`, `width`, `height`, `background`, `score`, `status`, `preview_url`, `prompt`, `provider`, `badge_label`, `badge_tone`, `design_notes`, `is_recommended`, `sort_order`, `meta_json`, `created_at`, `updated_at`) VALUES
(1, 1, 'white_studio_a', 'Beyaz Stüdyo A', 'Trendyol', '1200x1800', 1200, 1800, 'Beyaz Stüdyo', 96, 'ready', '/uploads/posts/ai_1775679575151757000.png', 'You are a senior ecommerce art director building a marketplace-ready PRODUCT IMAGE EDIT for Dio şirketi.\n\nGOAL:\n- Keep the uploaded product\'s silhouette, form factor, proportions, and recognizable identity faithful to the source.\n- Re-stage the product into a refined commercial visual suitable for \"Trendyol\".\n- Remove messy background distractions and create a polished Beyaz Stüdyo setup.\n\nSOURCE PRODUCT SUMMARY:\nA giyim & moda photographed in a casual source image. Preserve the original product silhouette, proportions, core color family, and material feel, while removing background clutter and upgrading the scene into a clean commercial ecommerce visual with refined lighting and realistic shadow.\n\nBRAND / MERCHANT CONTEXT:\n- Brand: Dio şirketi\n- Sector: moda\n- Category: Giyim & Moda\n- Audience: [\"impulsif\"]\n- Tone: \n- Brand colors: [\"#e6272f\",\"#1c1f26\"]\n\nOUTPUT SPEC:\n- Variant name: Beyaz Stüdyo A\n- Platform: Trendyol\n- Canvas: 1200x1800 px\n- Background direction: Beyaz Stüdyo\n- Design note: Pazar yeri uyumlu temiz beyaz zemin, ana ürün odağı yüksek.\n\nMANDATORY RULES:\n- This is a PRODUCT-FOCUSED image. Product must remain the hero.\n- Use clean ecommerce composition with strong product separation.\n- Do not add text, letters, labels, logos, watermarks, stickers, hands, or UI.\n- Improve lighting, shadow, edge clarity, depth, and material realism.\n- Background should feel intentional, premium, and conversion-oriented.\n- Keep enough breathing room around the product for cropping in marketplace cards.\n- If the source is a phone snapshot, transform it into a studio-grade commercial image.\n- Preserve the original product color family unless a subtle correction is needed for realism.\n\nVISUAL DIRECTION:\n- For white/neutral presets: use soft studio lighting, realistic contact shadow, calm reflections, catalog cleanliness.\n- For premium dark presets: use dramatic but controlled contrast, elegant vignette, premium texture, luxury ecommerce mood.\n- For social presets: keep product-first framing but allow tasteful atmosphere, subtle gradients, and richer color styling.\n\nRespond with a pure visual output only.', 'gemini', 'Trendyol', 'success', 'Pazar yeri uyumlu temiz beyaz zemin, ana ürün odağı yüksek.', 1, 0, '', '2026-04-08 23:19:28.218', '2026-04-08 23:19:35.153'),
(2, 1, 'cream_neutral_b', 'Krem Nötr B', 'Hepsiburada', '1200x1200', 1200, 1200, 'Krem Nötr', 91, 'ready', '/uploads/posts/ai_1775679582049686000.png', 'You are a senior ecommerce art director building a marketplace-ready PRODUCT IMAGE EDIT for Dio şirketi.\n\nGOAL:\n- Keep the uploaded product\'s silhouette, form factor, proportions, and recognizable identity faithful to the source.\n- Re-stage the product into a refined commercial visual suitable for \"Hepsiburada\".\n- Remove messy background distractions and create a polished Krem Nötr setup.\n\nSOURCE PRODUCT SUMMARY:\nA giyim & moda photographed in a casual source image. Preserve the original product silhouette, proportions, core color family, and material feel, while removing background clutter and upgrading the scene into a clean commercial ecommerce visual with refined lighting and realistic shadow.\n\nBRAND / MERCHANT CONTEXT:\n- Brand: Dio şirketi\n- Sector: moda\n- Category: Giyim & Moda\n- Audience: [\"impulsif\"]\n- Tone: \n- Brand colors: [\"#e6272f\",\"#1c1f26\"]\n\nOUTPUT SPEC:\n- Variant name: Krem Nötr B\n- Platform: Hepsiburada\n- Canvas: 1200x1200 px\n- Background direction: Krem Nötr\n- Design note: Yumuşak nötr tonlarla kategoriye daha sıcak bir raf hissi verir.\n\nMANDATORY RULES:\n- This is a PRODUCT-FOCUSED image. Product must remain the hero.\n- Use clean ecommerce composition with strong product separation.\n- Do not add text, letters, labels, logos, watermarks, stickers, hands, or UI.\n- Improve lighting, shadow, edge clarity, depth, and material realism.\n- Background should feel intentional, premium, and conversion-oriented.\n- Keep enough breathing room around the product for cropping in marketplace cards.\n- If the source is a phone snapshot, transform it into a studio-grade commercial image.\n- Preserve the original product color family unless a subtle correction is needed for realism.\n\nVISUAL DIRECTION:\n- For white/neutral presets: use soft studio lighting, realistic contact sha